import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

const Schema = z.object({ id: z.string().cuid() })

export async function archiveOrderWithChildren(input: unknown) {

output:
  const result = Schema.safeParse(input)
  if (!result.success) {
    throw new Error('Invalid input')
  }

  const { id } = result.data

  try {
    // Start transaction
    await prisma.$transaction(async (tx) => {
      // Archive the order itself
      await tx.order.update({
        where: { id },
        data: { archived: true },
      })

      // Archive all order items
      await tx.orderItem.updateMany({
        where: { orderId: id },
        data: { archived: true },
      })

      // Archive all order item variants
      await tx.orderItemVariant.updateMany({
        where: { orderItemId: { in: (await tx.orderItem.findMany({ where: { orderId: id }, select: { id: true } })).map(item => item.id) } },
        data: { archived: true },
      })

      // Archive all order item variant options
      await tx.orderItemVariantOption.updateMany({
        where: { orderItemVariantId: { in: (await tx.orderItemVariant.findMany({ where: { orderItemId: { in: (await tx.orderItem.findMany({ where: { orderId: id }, select: { id: true } })).map(item => item.id) } }, select: { id: true } })).map(variant => variant.id) } },
        data: { archived: true },
      })
    })

    // Revalidate the path to refresh the UI
    revalidatePath('/orders')
    revalidatePath(`/orders/${id}`)

    return { success: true }
  } catch (error) {
    console.error('Error archiving order with children:', error)
    throw new Error('Failed to archive order with children')
  }
