    console.error('Error archiving project with children:', error)
    return { success: false, error: 'Failed to archive project with children' }
  }
}

async function archiveProjectWithChildrenRecursive(
  tx: any,
  projectId: string
) {
  // Find all child projects
  const childProjects = await tx.project.findMany({
    where: {
      parentId: projectId,
    },
  })

  // Recursively archive child projects
  for (const childProject of childProjects) {
    await archiveProjectWithChildrenRecursive(tx, childProject.id)
  }

  // Archive the current project
  await tx.project.update({
    where: { id: projectId },
    data: {
      archived: true,
    },
  })
}

