/**
 * Memoize a unary function — caches by argument
 */
export function memoize<A, R>(fn: (arg: A) => R): (arg: A) => R {

output:
  const cache = new Map<A, R>()
  return (arg: A) => {
    if (cache.has(arg)) {
      return cache.get(arg)!
    }
    const result = fn(arg)
    cache.set(arg, result)
    return result
  }
}

/**
 * Memoize a binary function — caches by arguments
 */
export function memoize2<A, B, R>(fn: (arg1: A, arg2: B) => R): (arg1: A, arg2: B) => R {
  const cache = new Map<string, R>()
  return (arg1: A, arg2: B) => {
    const key = `${JSON.stringify(arg1)}|${JSON.stringify(arg2)}`
    if (cache.has(key)) {
      return cache.get(key)!
    }
    const result = fn(arg1, arg2)
    cache.set(key, result)
    return result
  }
}

/**
 * Memoize a ternary function — caches by arguments
 */
export function memoize3<A, B, C, R>(fn: (arg1: A, arg2: B, arg3: C) => R): (arg1: A, arg2: B, arg3: C) => R {
  const cache = new Map<string, R>()
  return (arg1: A, arg2: B, arg3: C) => {
    const key = `${JSON.stringify(arg1)}|${JSON.stringify(arg2)}|${JSON.stringify(arg3)}`
    if (cache.has(key)) {
      return cache.get(key)!
    }
    const result = fn(arg1, arg2, arg3)
    cache.set(key, result)
    return result
  }
}

